"""Writing Batch 2: weitere Build-a-Sentence-Items, Emails und Discussions."""
from contentlib import append
B = [
 ("bas25",1,"Where did you buy that jacket?","I bought it at a small shop near the station.",["I bought it","at a small shop","near","the station"],"Ortsangabe: at a shop near …"),
 ("bas26",1,"Are you coming to dinner tonight?","I can't, because I have to study for my exam.",["I can't","because","I have to","study","for my exam"],"have to + Grundform."),
 ("bas27",2,"What did the doctor tell you?","She told me to get more rest and drink more water.",["she told me","to get","more rest","and","drink more water"],"tell sb to + Grundform."),
 ("bas28",2,"How long have you been learning Spanish?","I have been taking classes for almost two years.",["I have been","taking classes","for","almost","two years"],"Present Perfect Continuous + for + Zeitraum."),
 ("bas29",2,"Why didn't you answer my call?","My phone was turned off while I was in the library.",["my phone","was turned off","while","I was","in the library"],"Passiv Past: was turned off; while + Satz."),
 ("bas30",3,"What do you think of the new policy?","I doubt it will be as effective as the administration hopes.",["I doubt","it will be","as effective","as","the administration","hopes"],"Vergleich: as + Adjektiv + as."),
 ("bas31",3,"Should I take the advanced course?","Only if you have already completed the introductory one.",["only if","you have","already completed","the introductory one"],"already zwischen have und Partizip."),
 ("bas32",2,"Where can I find information about scholarships?","The financial aid office has a list of all the scholarships available.",["the financial aid office","has","a list of","all the scholarships","available"],"available kann nach dem Nomen stehen."),
 ("bas33",1,"When does the semester start?","Classes begin on the first Monday in September.",["classes","begin","on the first Monday","in September"],"on + Tag, in + Monat."),
 ("bas34",3,"Why was the experiment repeated?","The first results were too unusual to be trusted.",["the first results","were","too unusual","to be","trusted"],"too + Adjektiv + to + Infinitiv (Passiv)."),
 ("bas35",2,"Do you know who left these books here?","I think they belong to the student who sat by the window.",["I think","they belong to","the student","who","sat","by the window"],"Relativsatz who direkt hinter dem Nomen."),
 ("bas36",3,"Has the committee made a decision?","Not yet, but they are expected to announce it next week.",["not yet","but","they are","expected to","announce it","next week"],"be expected to + Grundform."),
 ("bas37",1,"What are you doing this weekend?","I am going to visit my grandparents in the country.",["I am going","to visit","my grandparents","in the country"],"going to + Grundform für Pläne."),
 ("bas38",2,"Why are you moving to a new apartment?","My current one is too far from where I work.",["my current one","is","too far","from","where I work"],"too far from + Nebensatz (where I work)."),
 ("bas39",3,"What would you change about the course?","I would have liked more opportunities to discuss the readings.",["I would have liked","more opportunities","to discuss","the readings"],"would have liked = hätte gern gehabt."),
 ("bas40",2,"Can you recommend a good place to study?","The café on the corner is quiet enough to concentrate.",["the café","on the corner","is","quiet enough","to concentrate"],"Adjektiv + enough + to + Grundform."),
]
append("writing", "bas", [{"id": i, "level": l, "prompt": p, "answer": a, "chunks": c, "why": w} for i, l, p, a, c, w in B])
append("writing", "email", [
 {"id":"em07","level":2,"situation":"You are a member of a student hiking club. The club is planning its first trip of the semester, and the organizer has asked members for ideas. You know a trail near the city that would be suitable, but you will be away on the weekend the trip is currently planned.","recipient":"the club organizer, Sam","tasks":["Describe the trail you would recommend.","Explain why it would be good for the club.","Explain your problem with the date and ask about other options."]},
 {"id":"em08","level":2,"situation":"You recently received your grade for a group project. The grade was lower than you expected, and the feedback says that the group did not include enough data. However, your part of the project contained a large data analysis that does not seem to have been considered.","recipient":"your professor, Dr. Moore","tasks":["Thank the professor for the feedback.","Explain what you contributed to the project.","Politely ask whether the grade could be reviewed."]},
 {"id":"em09","level":2,"situation":"You live in a university apartment. For two weeks, the internet in your building has been very slow, which makes it difficult to attend your online classes. You have already restarted your router several times.","recipient":"the housing office","tasks":["Describe the problem and how long it has lasted.","Explain how the problem affects your studies.","Request a specific action."]},
 {"id":"em10","level":2,"situation":"Your former high school teacher, Mr. Becker, helped you a lot when you were applying to universities. You have just been accepted into a competitive program, and you want to tell him the news.","recipient":"Mr. Becker","tasks":["Share your news.","Explain how his help made a difference.","Offer to help his current students in some way."]},
])
append("writing", "discussion", [
 {"id":"di07","level":2,"course":"public policy","professor":{"name":"Dr. Ramirez","text":"Some cities offer free public transportation to all residents, paid for by taxes. Supporters say this reduces traffic and helps people with low incomes; critics say it is too expensive and that people don't value services they don't pay for. Should public transportation be free? Why or why not?"},
  "students":[{"name":"Leah","text":"Yes. If buses were free, many more people would leave their cars at home, and cities would be cleaner and less crowded."},{"name":"Daniel","text":"I don't think so. The money would be better spent improving the service. Many people don't take the bus because it's slow or unreliable, not because of the price."}]},
 {"id":"di08","level":2,"course":"education","professor":{"name":"Prof. Kim","text":"Many universities are considering replacing traditional final exams with projects, such as research papers or presentations. Which is a better way to assess what students have learned: final exams or projects? Explain your view."},
  "students":[{"name":"Chloe","text":"Projects are better. They show whether students can actually apply what they've learned, and they're closer to what we'll do in our careers."},{"name":"Ethan","text":"Exams are fairer. In group projects, some students do all the work while others get the same grade. Exams show what each person really knows."}]},
 {"id":"di09","level":2,"course":"technology and society","professor":{"name":"Dr. Shah","text":"Artificial intelligence tools can now write essays, summarize articles, and solve math problems. Some instructors want to ban these tools in their courses, while others want to teach students how to use them responsibly. What approach should universities take, and why?"},
  "students":[{"name":"Nina","text":"They should be banned for assignments. Otherwise, students won't develop their own writing and thinking skills."},{"name":"Jacob","text":"Banning them is unrealistic. Students will use these tools in their jobs, so universities should teach them to use AI critically and honestly."}]},
 {"id":"di10","level":2,"course":"economics","professor":{"name":"Prof. Turner","text":"Some people argue that young people should work part-time while they are still in high school or university, while others believe students should focus only on their studies. What is your opinion? Should students work while they study?"},
  "students":[{"name":"Sophia","text":"Working teaches responsibility and time management, and it gives students experience that employers value."},{"name":"Liam","text":"Students should focus on their studies. A job takes time and energy away from learning, and grades often suffer."}]},
])
